        public const string EditorRequestFile="TestResults/Planetary/ship-editor-request.txt";
        [Serializable]sealed class Report{public string status="PASS",error="",memoryScope="Unity tracked allocation/reservation, not total VRAM";public bool editor;public List<string> checks=new List<string>();public int colliders,rebases;public Vector3 lastFeet,cameraLocal;public float worstLocalDrift,maximumCameraOffset;public double movementMedianMs,movementP95Ms,cruiseMetresPerSecond,measuredCruiseMetresPerSecond;public long allocatedBytes,reservedBytes;}
        readonly Report report=new Report();readonly List<double> movement=new List<double>();PlanetDevelopment world;PlanetSpacecraft ship;PlanetFirstPersonController player;string output;RenderTexture target,hudTarget,hudComposite;Material hudMaterial;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){bool editor=Application.isEditor&&File.Exists(EditorRequestFile)&&FindAnyObjectByType<PlanetDevelopment>()!=null;if(editor)File.Delete(EditorRequestFile);if(editor||!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-ship-validation")>=0)new GameObject("Ship interaction regression").AddComponent<PlanetShipValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();report.editor=Application.isEditor;output=Application.isEditor?"TestResults/Planetary/Ship/EditorWarp":args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.sessionMode=PlanetGameMode.Rts;world.ambientZombies=0;world.requestedCapacity=4096;world.configuredRadius=120000;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Time.captureDeltaTime=1f/60;}
        void Start(){StartCoroutine(Guard());}
        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();UnityEngine.Debug.LogException(e);break;}yield return next;}if(player!=null)report.lastFeet=player.ShipLocalPosition;report.allocatedBytes=Profiler.GetTotalAllocatedMemoryLong();report.reservedBytes=Profiler.GetTotalReservedMemoryLong();movement.Sort();if(movement.Count>0){report.movementMedianMs=movement[movement.Count/2];report.movementP95Ms=movement[(int)((movement.Count-1)*.95)];}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Time.captureDeltaTime=0;
