            if(Application.isEditor){UnityEditor.EditorApplication.isPlaying=false;yield break;}
#endif
            Application.Quit(report.status=="PASS"?0:1);}
        void Check(bool valid,string message){if(!valid)throw new InvalidOperationException(message);report.checks.Add(message);}
        void CheckCruise(){
            var saved=ship.Pose;bool assist=ship.FlightAssistEnabled;
            double boundary=world.definition.radius+Math.Max(world.definition.ReliefBound+6000,world.definition.hasAtmosphere?world.definition.atmosphereHeight:0);
            var normal=new Double3(12,3,120);var state=new SpacePose{position=new Double3(0,boundary+50000,0),rotation=Quaternion.identity,linearVelocity=normal};
            ship.ResetForSystemValidation(state);ship.Integrate(.25f,Vector3.zero,Vector3.zero,cruise:true);
            Check(ship.CruiseActive&&Math.Abs(ship.Pose.linearVelocity.Magnitude-100000000)<.01&&(ship.Pose.position-state.position-new Double3(0,0,25000000)).Magnitude<.01,"Holding cruise moves the ship forward at 100,000 km/s without requiring thrust");
            Check((ship.NormalFlightVelocity-normal).Magnitude<1e-9,"Planet handoff receives the saved normal velocity rather than transient cruise momentum");
            var release=ship.Pose;release.linearVelocity=normal;ship.Integrate(.01f,Vector3.zero,Vector3.zero);var actual=ship.Pose;
            ship.ResetForSystemValidation(release);ship.Integrate(.01f,Vector3.zero,Vector3.zero);
            Check(!ship.CruiseActive&&(ship.Pose.position-actual.position).Magnitude<1e-7&&(ship.Pose.linearVelocity-actual.linearVelocity).Magnitude<1e-7,"Releasing cruise immediately resumes the normal flight integrator with the original velocity");
            ship.ResetForSystemValidation(state);const float slowFrame=.1f;
            for(int i=0;i<10;i++)ship.Integrate(ship.FlightStepDuration(slowFrame,true,false),Vector3.zero,Vector3.zero,cruise:true);
            report.cruiseMetresPerSecond=PlanetSpacecraft.CruiseSpeed;report.measuredCruiseMetresPerSecond=(ship.Pose.position-state.position).Magnitude/(slowFrame*10d);
            Check(Math.Abs(report.measuredCruiseMetresPerSecond-100000000)<.01,"Measured travel at 10 FPS is 100,000 km/s rather than being slowed by the normal physics cap");
            Check(ship.SpeedReadout==PlanetSpacecraft.CruiseSpeedReadout&&ship.SpeedReadout.Contains("km/s")&&PlanetSpacecraft.FormatFlightSpeed(120)=="120.0 m/s","The cockpit displays actual high flight speeds in km/s and ordinary flight in m/s");
            ship.ResetForSystemValidation(state);ship.SetFlightAssistance(true);ship.Integrate(.1f,Vector3.zero,Vector3.zero,cruise:true);ship.SetActive(false);
            Check(!ship.CruiseActive&&ship.FlightAssistEnabled&&(ship.Pose.linearVelocity-normal).Magnitude<1e-9,"Leaving the seat or losing control cancels transit and preserves flight assistance and normal speed");
            ship.ResetForSystemValidation(state);ship.ToggleRotationLock();ship.Integrate(.1f,Vector3.zero,Vector3.one,cruise:true);
            Check(ship.CruiseActive&&ship.RotationLocked&&ship.Pose.angularVelocity.sqrMagnitude>0,"Cruise retains orbital attitude hold and its rotating reference-frame velocity");ship.SetActive(false);
            Check(ship.RotationLocked&&!ship.CruiseActive&&(ship.Pose.linearVelocity-normal).Magnitude<1e-9,"Releasing transit retains orbital attitude hold and restores normal velocity");
            ship.ResetForSystemValidation(state);ship.Integrate(.1f,Vector3.zero,Vector3.zero,cruise:true);ship.Integrate(.01f,Vector3.zero,Vector3.zero,brake:true,cruise:true);
            Check(!ship.CruiseActive&&ship.Speed<200,"Braking overrides held cruise and removes transit momentum");
            state.position=new Double3(0,boundary+10000,0);state.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);ship.ResetForSystemValidation(state);ship.Integrate(2,Vector3.zero,Vector3.zero,cruise:true);
            Check(!ship.CruiseActive&&ship.Pose.position.Magnitude>=boundary&&ship.Pose.position.Magnitude<=boundary+2&&ship.Speed<200,"A long cruise step stops outside the atmosphere or terrain safety sphere instead of tunnelling through the planet");
            state.position=new Double3(0,boundary-100,0);state.rotation=Quaternion.identity;ship.ResetForSystemValidation(state);ship.Integrate(.01f,Vector3.zero,Vector3.zero,cruise:true);
            Check(!ship.CruiseActive&&ship.Speed<200,"Cruise is unavailable below the space-flight boundary");
            ship.ResetForSystemValidation(saved);ship.SetFlightAssistance(assist);Sync();
        }
        void Sync(){ship.Rebase();world.Base.Rebase();Physics.SyncTransforms();}
        void Walk(Vector2 input,int steps){for(int i=0;i<steps;i++){Sync();var timer=Stopwatch.StartNew();player.Step(1f/60,input,Vector2.zero);timer.Stop();movement.Add(timer.Elapsed.TotalMilliseconds);report.maximumCameraOffset=Mathf.Max(report.maximumCameraOffset,world.View.transform.position.magnitude);Sync();}}
        IEnumerator WaitDoor(){for(int i=0;i<36;i++)yield return null;Sync();}
        void Capture(string name){report.lastFeet=player.ShipLocalPosition;report.cameraLocal=ship.RenderToLocal(world.View.transform.position);if(target==null){target=new RenderTexture(1440,900,24,RenderTextureFormat.ARGBHalf);target.Create();world.View.enabled=false;world.View.targetTexture=target;}RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});var old=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();int visible=image.GetPixels32().Count(c=>c.r>10||c.g>10||c.b>10);File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=old;Check(visible>1000,name+" contains visible rendered geometry (lit pixels: "+visible+")");}
        IEnumerator Run(){while(world.ShipForValidation==null)yield return null;ship=world.ShipForValidation;player=world.PlayerForValidation;world.Paused=true;world.AutomaticPlayerStep=false;world.Rig.InputEnabled=false;player.CaptureCursor=false;world.SetFirstPerson(true);Sync();
            var parked=ship.Pose;ship.Integrate(.1f,Vector3.one,Vector3.one,cruise:true);Check(ship.Landed&&!ship.CruiseActive&&(ship.Pose.position-parked.position).Magnitude==0,"Holding cruise cannot move a landed capital ship");
            if(Application.isEditor){CheckCruise();yield break;}
            report.colliders=ship.VisualForValidation.GetComponentsInChildren<Collider>(true).Length;Check(report.colliders>=25&&report.colliders<80,"Ship collision uses a bounded shell of native colliders");Check(ship.DoorCount==2&&ship.Sealed,"Exterior hatch and inner airlock start closed");
            // Board from actual terrain using the ramp; no automatic seat teleport.
            var outside=ship.LocalToBody(new Vector3(0,-8,-54));player.EnterBodyPosition(outside,ship.Rotation*Vector3.forward);Walk(Vector2.up,150);Check(player.AttachedToShip,"Walking from terrain onto the ramp transfers the observer into ShipFrame");Check(player.ShipLocalPosition.z<-38.5f&&player.ShipLocalPosition.z>-40,"Closed outer hatch blocks capsule movement");yield return null;yield return new WaitForEndOfFrame();Capture("closed-rear-hatch");
            Check(world.Interact(),"F interaction opens the exterior hatch from the ramp");yield return WaitDoor();Check(ship.DoorFraction(0)>.99f,"Outer hatch physically slides out of the opening");Check(ship.PressurizedAt(new Vector3(0,-4,0))&&!ship.PressurizedAt(new Vector3(0,-4,-35)),"Closed inner airlock protects cabin pressure while the outer hatch is open");Walk(Vector2.up,95);Check(player.ShipLocalPosition.z<-31.4f&&player.ShipLocalPosition.z>-32.2f,"Closed inner airlock blocks entry after the outer hatch opens");Check(world.Interact(),"F interacts with the inner airlock from inside the vestibule");yield return WaitDoor();Walk(Vector2.up,95);Check(player.ShipLocalPosition.z>-30&&player.Grounded&&Mathf.Abs(player.ShipLocalPosition.y+4)<.08f,"Player walks through both open hatches and stands on the interior deck");yield return null;yield return new WaitForEndOfFrame();Capture("main-corridor");
            player.EnterShip(ship,new Vector3(0,-4,-38.25f),Vector3.forward);Check(!ship.ToggleDoor(0),"A hatch cannot close through an occupant");player.EnterShip(ship,new Vector3(0,-4,-35),Vector3.forward);Check(ship.ToggleDoor(0),"A clear hatch can begin closing");for(int i=0;i<5;i++)yield return null;player.EnterShip(ship,new Vector3(0,-4,-38.25f),Vector3.forward);yield return WaitDoor();Check(ship.DoorFraction(0)>.99f,"Entering a closing hatch automatically reopens it");
            player.EnterShip(ship,new Vector3(0,-4,-16),Vector3.left);Walk(Vector2.up,150);Check(player.ShipLocalPosition.x>=-7.47f,"Interior bulkheads stop the capsule at its radius (x="+player.ShipLocalPosition.x.ToString("F4")+")");player.EnterShip(ship,new Vector3(0,-4,-8),Vector3.left);Walk(Vector2.up,130);Check(player.ShipLocalPosition.x<-10&&ship.RoomName(player.ShipLocalPosition)=="COMMAND ROOM","Player walks through a bulkhead opening into the command room");yield return null;yield return new WaitForEndOfFrame();Capture("command-room");
            // Native building collision shares the same observer motor.
            var building=world.Base.Buildings.First(b=>b.team==0&&b.definition.id=="command");var bounds=building.visual.GetComponent<BoxCollider>();var local=new Vector3(bounds.center.x+bounds.size.x*.5f+3,bounds.center.y-bounds.size.y*.5f+.05f,bounds.center.z);var render=building.visual.transform.TransformPoint(local);player.EnterBodyPosition(world.RenderToBody(render),building.visual.transform.TransformDirection(Vector3.left));Walk(Vector2.up,90);var at=building.visual.transform.InverseTransformPoint(world.RenderBodyPosition(player.PreciseBodyPosition));Check(at.x>=bounds.center.x+bounds.size.x*.5f+.2f,"The FPS capsule also collides with existing base infrastructure");
            player.EnterShip(ship,new Vector3(0,-4,-20),Vector3.forward);world.Rig.Origin.Rebased+=OnRebase;var initial=player.ShipLocalPosition;int objects=ship.VisualForValidation.GetComponentsInChildren<Collider>(true).Length;
            Sync();Check(ship.TakeOff(),"Occupied ship explicitly takes off before translation and rotation");for(int step=0;step<900&&ship.AutoFlightActive;step++){ship.Integrate(1f/60,Vector3.zero,Vector3.zero);Sync();Walk(Vector2.zero,1);report.worstLocalDrift=Mathf.Max(report.worstLocalDrift,Vector3.Distance(initial,player.ShipLocalPosition));}Check(!ship.AutoFlightActive,"Occupied takeoff completes its animated transition");ship.SetFlightAssistance(false);for(int i=0;i<1200;i++){ship.Integrate(1f/60,Vector3.up,new Vector3(0,.1f,.025f),boost:true);Sync();Walk(Vector2.zero,1);report.worstLocalDrift=Mathf.Max(report.worstLocalDrift,Vector3.Distance(initial,player.ShipLocalPosition));}
            Check(report.rebases>=2,"Occupied ship flight repeatedly anchors the client render origin");Check(report.worstLocalDrift<.005f,"A standing occupant keeps its local deck position during ship translation and rotation");world.AutomaticPlayerStep=true;world.Paused=false;for(int live=0;live<10;live++)yield return null;world.Paused=true;world.AutomaticPlayerStep=false;Check(ship.ActiveCabinLights>0&&ship.ActiveCabinLights<=2,"Cabin lighting follows the local observer during high-speed flight with at most two active lights");Check(objects==ship.VisualForValidation.GetComponentsInChildren<Collider>(true).Length,"Flight creates no extra colliders or per-unit objects");var expected=ship.ResolvePlayer(player.ShipLocalPosition+Vector3.up*player.EyeHeight,Quaternion.identity);Check(Vector3.Distance(world.View.transform.position,world.Rig.Origin.RenderPosition(expected.position))<.005f,"Ship-local player camera resolves accurately after origin shifts");
            Check(report.maximumCameraOffset==0,"FPS camera remains exactly zero on terrain, buildings and the moving ship");var velocityProbe=new Vector3(2,-4,27);Check(((ship.ResolvePlayer(velocityProbe,Quaternion.identity).linearVelocity-world.definition.velocity).Float-ship.VelocityAt(velocityProbe)).magnitude<.001f,"Canonical frame velocity includes planet translation and ship rotation for later replication");
            player.EnterShip(ship,new Vector3(0,-4,27),Vector3.forward);Sync();Walk(Vector2.zero,1);Check(world.Interact()&&world.IsPiloting&&!player.Active,"F at the pilot seat transfers exclusive control to flight");Check(world.View.transform.position==Vector3.zero,"Pilot camera anchors immediately, including while simulation is paused");if(Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-orbit-hud-capture")>=0){hudTarget=new RenderTexture(1440,900,0,RenderTextureFormat.ARGB32);hudTarget.Create();hudComposite=new RenderTexture(1440,900,0,RenderTextureFormat.ARGB32);hudComposite.Create();ship.SetPilotRenderTarget(hudTarget);world.Paused=false;for(int hudFrame=0;hudFrame<8;hudFrame++)yield return null;world.Paused=true;yield return new WaitForEndOfFrame();RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});hudMaterial=new Material(Resources.Load<Shader>("MassiveArmy/PlanetUiComposite"));hudMaterial.SetTexture("_Ui",hudTarget);Graphics.Blit(target,hudComposite,hudMaterial);var previousTarget=RenderTexture.active;RenderTexture.active=hudTarget;var hudImage=new Texture2D(1440,900,TextureFormat.RGBA32,false);hudImage.ReadPixels(new Rect(0,0,1440,900),0,0);hudImage.Apply();int hudPixels=hudImage.GetPixels32().Count(c=>c.g>70&&c.b>70&&c.a>20);RenderTexture.active=hudComposite;hudImage.ReadPixels(new Rect(0,0,1440,900),0,0);hudImage.Apply();File.WriteAllBytes(Path.Combine(output,"pilot-orbit-hud.png"),hudImage.EncodeToPNG());RenderTexture.active=previousTarget;Destroy(hudImage);Check(hudPixels>1000,"Pilot trajectory HUD renders with visible text and orbit geometry through the live cockpit camera");ship.SetPilotRenderTarget(null);}Check(world.Interact()&&world.IsFirstPerson&&player.Active&&player.AttachedToShip,"F while piloting safely returns the player to the moving bridge");Check(player.Collision.Clear(ship.LocalToRender(player.ShipLocalPosition),ship.Rotation*Vector3.up),"Pilot-seat exit has capsule clearance");yield return null;yield return new WaitForEndOfFrame();Capture("bridge-after-seat-exit");var saved=player.ShipLocalPosition;world.SetFirstPerson(false);yield return null;yield return null;Check(!world.IsFirstPerson&&!world.IsPiloting,"Explicit RTS return releases FPS controls");Check(world.View.transform.position==Vector3.zero,"Returning to RTS keeps the camera at zero");world.SetFirstPerson(true);Sync();Check(player.AttachedToShip&&Vector3.Distance(saved,player.ShipLocalPosition)<.001f,"Returning from RTS restores the same ship-local occupant pose");
            CheckCruise();
        }
        void OnRebase(Vector3 shift){report.rebases++;}
        void OnDestroy(){if(world!=null){world.AutomaticPlayerStep=true;if(world.Rig!=null)world.Rig.Origin.Rebased-=OnRebase;}if(target!=null){target.Release();Destroy(target);}if(hudTarget!=null){hudTarget.Release();Destroy(hudTarget);}if(hudComposite!=null){hudComposite.Release();Destroy(hudComposite);}if(hudMaterial!=null)Destroy(hudMaterial);}
    }
